const TokenModal = memo(({ 
  showTokenModal, 
  setShowTokenModal, 
  selectedToken, 
  setSelectedToken, 
  tokens, 
  firebaseRef, 
  initialGameState, 
  layers, 
  initiative, 
  inCombat, 
  currentTurn, 
  THEME 
}) => (
  <Modal
    visible={showTokenModal}
    transparent={true}
    animationType="fade"
    onRequestClose={() => setShowTokenModal(false)}
  >
    <Pressable 
      style={[styles.modalOverlay, { cursor: 'default' }]}
      onPress={() => Keyboard.dismiss()}
    >
      <View style={styles.modalContent}>
        <KeyboardAvoidingView 
          behavior={Platform.select({ ios: 'padding', android: 'height' })}
          style={styles.modalContainer}
          keyboardVerticalOffset={Platform.select({ ios: 64, android: 0 })}
        >
          <Pressable onPress={e => e.stopPropagation()}>
            <Text style={styles.modalTitle}>Edit Token</Text>
            <TextInput
              style={styles.input}
              value={selectedToken?.name}
              onChangeText={(text) => {
                setSelectedToken(prev => ({
                  ...prev,
                  name: text
                }));
              }}
              placeholder="Token Name"
              placeholderTextColor={THEME.text.light + '80'}
              blurOnSubmit={false}
              autoComplete="off"
              spellCheck={false}
              selectTextOnFocus={true}
              enablesReturnKeyAutomatically={true}
            />

            <View style={{ flexDirection: 'row', gap: 10, marginBottom: 10 }}>
              <View style={{ flex: 1 }}>
                <TextInput
                  style={styles.input}
                  value={String(selectedToken?.hp || '')}
                  onChangeText={(text) => {
                    const hp = parseInt(text) || 0;
                    setSelectedToken(prev => ({
                      ...prev,
                      hp: Math.max(0, hp)
                    }));
                  }}
                  keyboardType="numeric"
                  placeholder="Current HP"
                  placeholderTextColor={THEME.text.light + '80'}
                  blurOnSubmit={false}
                  autoComplete="off"
                  selectTextOnFocus={true}
                  enablesReturnKeyAutomatically={true}
                />
              </View>
              <View style={{ flex: 1 }}>
                <TextInput
                  style={styles.input}
                  value={String(selectedToken?.maxHp || '')}
                  onChangeText={(text) => {
                    const maxHp = parseInt(text) || 1;
                    setSelectedToken(prev => ({
                      ...prev,
                      maxHp: Math.max(1, maxHp)
                    }));
                  }}
                  keyboardType="numeric"
                  placeholder="Max HP"
                  placeholderTextColor={THEME.text.light + '80'}
                  blurOnSubmit={false}
                  autoComplete="off"
                  selectTextOnFocus={true}
                  enablesReturnKeyAutomatically={true}
                />
              </View>
            </View>

            <TextInput
              style={styles.input}
              value={String(selectedToken?.initiativeBonus || '0')}
              onChangeText={(text) => {
                setSelectedToken(prev => ({
                  ...prev,
                  initiativeBonus: parseInt(text) || 0
                }));
              }}
              keyboardType="numeric"
              placeholder="Initiative Bonus"
              placeholderTextColor={THEME.text.light + '80'}
              blurOnSubmit={false}
              autoComplete="off"
              selectTextOnFocus={true}
              enablesReturnKeyAutomatically={true}
            />

            <View style={statusStyles.effectsContainer}>
              <Text style={statusStyles.effectsTitle}>Status Effects</Text>
              <View style={statusStyles.effectsGrid}>
                {STATUS_EFFECTS.map(effect => (
                  <TouchableOpacity
                    key={effect.id}
                    style={[
                      statusStyles.effectButton,
                      selectedToken?.effects?.includes(effect.id) && statusStyles.effectActive
                    ]}
                    onPress={() => {
                      setSelectedToken(prev => {
                        const currentEffects = prev.effects || [];
                        const newEffects = currentEffects.includes(effect.id)
                          ? currentEffects.filter(e => e !== effect.id)
                          : [...currentEffects, effect.id];
                        return {
                          ...prev,
                          effects: newEffects
                        };
                      });
                    }}
                  >
                    <Text style={statusStyles.effectText}>
                      {effect.icon} {effect.name}
                    </Text>
                  </TouchableOpacity>
                ))}
              </View>
            </View>

            <View style={styles.modalButtons}>
              <TouchableOpacity
                style={[styles.modalButton, { backgroundColor: THEME.danger }]}
                onPress={() => {
                  if (firebaseRef.current && selectedToken) {
                    const newTokens = { ...tokens };
                    delete newTokens[selectedToken.position];
                    set(firebaseRef.current, { 
                      ...initialGameState,
                      tokens: newTokens,
                      layers,
                      initiative,
                      inCombat,
                      currentTurn
                    });
                    setShowTokenModal(false);
                  }
                }}
              >
                <Text style={styles.buttonText}>Delete</Text>
              </TouchableOpacity>

              <TouchableOpacity
                style={[styles.modalButton, { backgroundColor: THEME.success }]}
                onPress={() => {
                  if (firebaseRef.current && selectedToken) {
                    const newTokens = {
                      ...tokens,
                      [selectedToken.position]: selectedToken
                    };
                    set(firebaseRef.current, {
                      ...initialGameState,
                      tokens: newTokens,
                      layers,
                      initiative,
                      inCombat,
                      currentTurn
                    });
                    setShowTokenModal(false);
                  }
                }}
              >
                <Text style={styles.buttonText}>Save</Text>
              </TouchableOpacity>
            </View>
          </Pressable>
        </KeyboardAvoidingView>
      </View>
    </Pressable>
  </Modal>
));

