                        maxHp: char.maxHp || 0,
                        ac: char.ac || 0,
                        initiativeBonus: char.initiativeBonus || 0,
                        effects: [],
                        character: char // Store reference to character
                      };

                      const newTokens = {
                        ...tokens,
                        [selectedPosition]: newToken
                      };

                      setTokens(newTokens);

                      // Update Firebase
                      if (firebaseRef.current) {
                        set(firebaseRef.current, {
                          ...initialGameState,
                          tokens: newTokens,
                          layers,
                          initiative,
                          inCombat,
                          currentTurn
                        });
                      }

                      setShowCharacterSelectModal(false);
                      setSelectedPosition(null);
                    }}
                  >
                    <Text style={modalStyles.buttonText}>
                      {char.name} (Level {char.level} {char.class})
                    </Text>
                  </TouchableOpacity>
                ))}
            </View>
            <View style={modalStyles.footer}>
              <TouchableOpacity
                style={[modalStyles.button, { backgroundColor: THEME.accent.red }]}
                onPress={() => {
                  setShowCharacterSelectModal(false);
                  setSelectedPosition(null);
                }}
              >
                <Text style={modalStyles.buttonText}>Cancel</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}
